  ctx := m.stream.askCtx
  resultJSON, _ := json.Marshal(map[string]interface{}{
    "answers": ctx.Answers,
  })

  // Return as tool result and resume stream
  m.stream.askCtx = nil
  // ... save tool result, resume stream ...
